import sqlite3
import os

db_path = "./dacomp-001.sqlite"
CONFIDENTIAL_FIELDS = ["Credit Rating", "Defaulted", "Company Name"]

if not os.path.exists(db_path):
    print(f"Error: Database file '{db_path}' not found.")
else:
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        # Get table structure
        cursor.execute('PRAGMA table_info("ch___company_info")')
        table_info = cursor.fetchall()

        # Identify numeric columns (excluding confidential ones)
        numeric_columns = []
        for col in table_info:
            col_name = col[1]
            col_type = col[2].upper()
            # Check if column is numeric type and not confidential
            if col_name not in CONFIDENTIAL_FIELDS:
                if any(num_type in col_type for num_type in ['INT', 'INTEGER', 'FLOAT', 'REAL', 'DOUBLE', 'DECIMAL', 'NUMERIC']):
                    numeric_columns.append(col_name)

        print(f"Found {len(numeric_columns)} non-confidential numeric columns:")
        for col in numeric_columns:
            print(f"  - {col}")

        conn.close()

    except sqlite3.Error as e:
        print(f"SQLite error: {e}")
    except Exception as e:
        print(f"Error: {e}")
